import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem97 nao autentica calcado nem garante desempenho ou servicos da TV',()=>{for(const [id,titulo] of [['mlMLB4291654613','Tênis Vizzano Feminino Casual Original Confortável Moda 1430'],['mlMLB4367472775','Smart Tv 43 Philco P43vik Roku Led Dolby Audio Wi-fi Hdmi Hdr Full Hd 110/220v']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.equal(x.titulo,titulo);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/catálogo confirmado|conforto comprovado|som imersivo|navegação fluida|4K/i);}});
